/** Rich, original product sections; launch actions connect to the same live workspace. */
export function initLandingExplorer({closeMenus}){
  const $=s=>document.querySelector(s);
  const section=document.createElement('section');section.className='solutions-section section-pad shell';section.id='solutions';
  section.innerHTML=`<div class="section-heading"><div><div class="eyebrow">MADE FOR THE WAY YOU WORK</div><h2>Different starting points.<br><span class="muted">The same creative momentum.</span></h2></div><p>Explore three workflows.<br>Then step inside and make one your own.</p></div><div class="solution-showcase"><div class="solution-navigation" role="tablist" aria-label="Explore workflows"><button role="tab" id="solution-build-tab" aria-controls="solution-build" aria-selected="true" data-solution="build"><span class="solution-icon">⌁</span><div><b>For the builders</b><small>Turn a starting point into a working screen.</small></div><i>01</i></button><button role="tab" id="solution-design-tab" aria-controls="solution-design" aria-selected="false" tabindex="-1" data-solution="design"><span class="solution-icon">◈</span><div><b>For the design-minded</b><small>Keep the details connected to the code.</small></div><i>02</i></button><button role="tab" id="solution-private-tab" aria-controls="solution-private" aria-selected="false" tabindex="-1" data-solution="private"><span class="solution-icon">⌘</span><div><b>For the locally grounded</b><small>Make the boundaries part of the workflow.</small></div><i>03</i></button><div class="solution-footnote"><span class="status-dot"></span> INTERACTIVE WORKFLOW CONCEPTS</div></div><div class="solution-panels">
  <article role="tabpanel" id="solution-build" aria-labelledby="solution-build-tab"><div class="solution-panel-header"><span>BLUEPRINT / BUILD</span><span>01 — 03</span></div><div class="builder-preview"><div class="builder-sidebar"><span>⑂ next-chapter</span><b>▾ src</b><small>▾ components</small><span class="preview-file">⌁ WorkspaceScreen.jsx</span><small>◇ design-tokens.json</small><small>⌘ decisions.md</small><div><i class="status-dot"></i> Your intent, in view</div></div><div class="builder-canvas"><span class="builder-frame-label">YOUR NEXT SCREEN</span><div class="builder-sample-card"><span class="builder-orbit">✳</span><b>A little structure.<br>A lot of possibility.</b><p>Your next chapter starts here.</p><span class="sample-button">Open the project ↗</span></div><div class="builder-trace"><span><i>✓</i> Shape</span><b>→</b><span><i>⌁</i> Inspect</span><b>→</b><span><i>◎</i> Verify</span></div></div></div><div class="solution-panel-copy"><div><h3>From a blank page to a clear next step.</h3><p>Choose a screen, shape its properties, and inspect the generated React.</p></div><button data-launch-solution="build">Try this workflow <span>↗</span></button></div></article>
  <article role="tabpanel" id="solution-design" aria-labelledby="solution-design-tab" hidden><div class="solution-panel-header"><span>BLUEPRINT / DESIGN</span><span>02 — 03</span></div><div class="design-workflow-preview"><div class="token-source"><span>DESIGN TOKEN</span><div class="token-large-swatch"></div><code>color.accent</code><div class="solution-swatches" role="group" aria-label="Preview an accent token"><button data-solution-accent="blue" aria-label="Preview blue token" aria-pressed="true"></button><button data-solution-accent="violet" aria-label="Preview violet token" aria-pressed="false"></button><button data-solution-accent="mint" aria-label="Preview mint token" aria-pressed="false"></button></div></div><span class="token-connection">⇄</span><div class="token-instances"><div><span>BUTTON / PRIMARY</span><b>Start something ↗</b></div><div><span>STATUS / ACTIVE</span><i></i><strong>In your orbit</strong></div><div><span>CODE / SHARED VALUE</span><code>accent: <em>token.accent</em></code></div></div></div><div class="solution-panel-copy"><div><h3>One detail. Every connected instance.</h3><p>Try a token above, then open the dashboard and keep exploring.</p></div><button data-launch-solution="design">Explore the canvas <span>↗</span></button></div></article>
  <article role="tabpanel" id="solution-private" aria-labelledby="solution-private-tab" hidden><div class="solution-panel-header"><span>BLUEPRINT / LOCAL</span><span>03 — 03</span></div><div class="private-workflow-preview"><div class="private-route-label"><i class="status-dot"></i><span id="route-label">LOCAL-ONLY ROUTING</span></div><div class="route-machine"><span>YOUR WORKSPACE</span><div class="route-computer">▱<b>BN</b></div><div><span>⌘ Memory</span><span>⌁ Code</span><span>◈ Canvas</span></div></div><div class="route-line"><i></i></div><div class="route-cloud"><span>☁</span><small>OPTIONAL PROVIDER</small></div><div class="route-options" role="group" aria-label="Illustrate a routing boundary"><button data-route="local" aria-pressed="true">Local first</button><button data-route="optional" aria-pressed="false">Explicit cloud scope</button></div><span class="route-disclaimer" id="route-disclaimer">A proposed product boundary. No external request is made.</span></div><div class="solution-panel-copy"><div><h3>Your boundaries belong in the interface.</h3><p>Inspect a settings screen with editable example routing preferences.</p></div><button data-launch-solution="private">Open the settings <span>↗</span></button></div></article>
  </div></div>`;
  $('.stack-strip').after(section);
  section.querySelector('h2').innerHTML='Pick a workflow.<br><span class="muted">Make it yours.</span>';section.querySelector('.section-heading>p').textContent='Three starting points. Each opens a screen you can edit in the working demo.';
  section.querySelector('[data-solution="build"] b').textContent='Build a screen';section.querySelector('[data-solution="design"] b').textContent='Refine a design';section.querySelector('[data-solution="private"] b').textContent='Set your boundaries';
  let accent='blue';const templates={build:'welcome',design:'dashboard',private:'settings'};
  const solutionTabs=[...section.querySelectorAll('[data-solution]')];
  function selectSolution(id,focus=false){solutionTabs.forEach(b=>{const chosen=b.dataset.solution===id;b.setAttribute('aria-selected',chosen);b.tabIndex=chosen?0:-1;if(chosen&&focus)b.focus();});section.querySelectorAll('[role=tabpanel]').forEach(p=>p.hidden=p.id!==`solution-${id}`);}
  solutionTabs.forEach(b=>b.addEventListener('click',()=>selectSolution(b.dataset.solution)));
  $('.solution-navigation').addEventListener('keydown',e=>{const index=solutionTabs.indexOf(document.activeElement);if(index<0)return;let next=index;if(['ArrowDown','ArrowRight'].includes(e.key))next=(index+1)%3;else if(['ArrowUp','ArrowLeft'].includes(e.key))next=(index+2)%3;else if(e.key==='Home')next=0;else if(e.key==='End')next=2;else return;e.preventDefault();selectSolution(solutionTabs[next].dataset.solution,true);});
  section.querySelectorAll('[data-solution-accent]').forEach(b=>b.addEventListener('click',()=>{accent=b.dataset.solutionAccent;section.style.setProperty('--sample-accent',{blue:'#459eff',violet:'#a68aff',mint:'#6ddab6'}[accent]);section.querySelectorAll('[data-solution-accent]').forEach(x=>x.setAttribute('aria-pressed',x===b));}));
  section.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>{const optional=b.dataset.route==='optional';$('.private-workflow-preview').classList.toggle('optional-route',optional);section.querySelectorAll('[data-route]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#route-label').textContent=optional?'EXPLICIT DESTINATION / EXPLICIT PERMISSION':'LOCAL-ONLY ROUTING';$('#route-disclaimer').textContent=optional?'Illustration only. Enabling a provider would require its own scope.':'A proposed product boundary. No external request is made.';}));
  section.querySelectorAll('[data-launch-solution]').forEach(b=>b.addEventListener('click',()=>document.dispatchEvent(new CustomEvent('bn:open-workspace',{detail:{template:templates[b.dataset.launchSolution],accent:b.dataset.launchSolution==='design'?accent:undefined,tab:'canvas',trigger:b}}))));

  const architecture=document.createElement('section');architecture.className='architecture-section section-pad';architecture.id='architecture';
  architecture.innerHTML=`<div class="shell"><div class="section-heading"><div><div class="eyebrow">THE INTELLIGENCE BETWEEN THE TOOLS</div><h2>A connected foundation.<br><span class="muted">A clearer picture.</span></h2></div><p>Click a layer to explore its role.<br>Then inspect it in the live browser workspace.</p></div><div class="architecture-layout"><div class="architecture-map" aria-label="Explore the proposed workspace architecture"><svg class="architecture-wires" viewBox="0 0 620 420" aria-hidden="true"><defs><radialGradient id="map-glow"><stop stop-color="#24569e" stop-opacity=".3"/><stop offset="1" stop-color="#10213b" stop-opacity="0"/></radialGradient></defs><circle cx="310" cy="210" r="190" fill="url(#map-glow)"/><circle cx="310" cy="210" r="120"/><circle cx="310" cy="210" r="172"/><path data-wire="memory" d="M310 210 C270 210 250 100 155 100"/><path data-wire="canvas" d="M310 210 C350 210 370 100 465 100"/><path data-wire="code" d="M310 210 C270 210 250 320 155 320"/><path data-wire="evaluation" d="M310 210 C350 210 370 320 465 320"/></svg><div class="architecture-core"><span>✳</span><b>YOUR INTENT</b><small>ONE PROJECT CONTEXT</small></div><div role="group" aria-label="Architecture layers"><button class="architecture-node memory-node-position" data-layer="memory" aria-pressed="true"><i>⌘</i><span>Project memory<small>CONTEXT WITH A SOURCE</small></span><b>↗</b></button><button class="architecture-node canvas-node-position" data-layer="canvas" aria-pressed="false"><i>◈</i><span>Editable canvas<small>INTENT MADE VISIBLE</small></span><b>↗</b></button><button class="architecture-node code-node-position" data-layer="code" aria-pressed="false"><i>⌁</i><span>Connected code<small>CHANGES YOU CAN READ</small></span><b>↗</b></button><button class="architecture-node evidence-node-position" data-layer="evaluation" aria-pressed="false"><i>◎</i><span>Visible evidence<small>OUTCOMES YOU CAN CHECK</small></span><b>↗</b></button></div><div class="architecture-map-label"><span class="status-dot"></span> PROPOSED SYSTEM / INTERACTIVE BLUEPRINT</div></div><div class="architecture-detail"><span class="architecture-detail-index" id="architecture-index">01 / REMEMBER</span><h3 id="architecture-title"></h3><p id="architecture-description"></p><ul id="architecture-points"></ul><span class="architecture-requirement" id="architecture-requirement"></span><button class="button button-small" id="architecture-open">Open project memory <span>↗</span></button></div></div></div>`;
  $('.connected-section').after(architecture);
  architecture.querySelector('h2').innerHTML='Here’s how<br><span class="muted">it fits together.</span>';
  const details={memory:{index:'01 / REMEMBER',title:'Context that carries forward.',description:'The proposed memory layer connects a decision to its source, project, branch, and moment in time.',points:['Inspect the evidence behind a remembered decision.','Correct, pin, or supersede project knowledge.','Keep retrieval within its authorized scope.'],requirement:'PRD / FR MEM 02–05',action:'Open project memory'},canvas:{index:'02 / CREATE',title:'Design you can keep shaping.',description:'Structured objects, supported components, and reusable tokens keep the interface editable.',points:['Start with a welcome, dashboard, or settings screen.','Change text, spacing, radius, and accent tokens.','Undo a change without losing the entire screen.'],requirement:'PRD / FR CAN 01–04',action:'Open the editable canvas'},code:{index:'03 / INSPECT',title:'A clear view of what changed.',description:'The intended product makes code changes reviewable against their base revision. This demo compares generated files with your saved checkpoint.',points:['Inspect generated React and design-token files.','Save a browser-local checkpoint.','Compare and export a text patch.'],requirement:'PRD / FR IDE 02, 05',action:'Inspect generated code'},evaluation:{index:'04 / VERIFY',title:'An outcome with a trail.',description:'Required checks and observed results belong alongside the artifact. This demo runs a small, real fixture suite against its current configuration.',points:['See passing and failing checks separately.','Retain a snapshot of each explicit check run.','Download evidence with its validation limits.'],requirement:'PRD / FR EVA 01–02',action:'Explore the evidence'}};
  let current='memory';
  function selectLayer(id){current=id;const item=details[id];architecture.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.layer===id));architecture.querySelectorAll('[data-wire]').forEach(p=>p.classList.toggle('active',p.dataset.wire===id));$('#architecture-index').textContent=item.index;$('#architecture-title').textContent=item.title;$('#architecture-description').textContent=item.description;$('#architecture-requirement').textContent=item.requirement;$('#architecture-points').replaceChildren(...item.points.map(text=>Object.assign(document.createElement('li'),{textContent:text})));$('#architecture-open').replaceChildren(document.createTextNode(item.action),Object.assign(document.createElement('span'),{textContent:'↗'}));}
  architecture.querySelectorAll('[data-layer]').forEach(b=>b.addEventListener('click',()=>selectLayer(b.dataset.layer)));$('#architecture-open').addEventListener('click',e=>document.dispatchEvent(new CustomEvent('bn:open-workspace',{detail:{tab:current,trigger:e.currentTarget}})));selectLayer('memory');
}
